<?php
namespace Database\Factories; use App\Models\WorkProcess; use Illuminate\Database\Eloquent\Factories\Factory; use Illuminate\Support\Str; class WorkProcessFactory extends Factory { protected $model=WorkProcess::class; public function definition():array{$title=fake()->unique()->words(3,true);return ['title'=>Str::title($title),'slug'=>Str::slug($title),'short_description'=>fake()->sentence(),'template'=>'standard','hero_style'=>'standard','status'=>'draft','display_order'=>1,'robots_index'=>true,'robots_follow'=>true];} public function published():static{return $this->state(fn()=>['status'=>'published','published_at'=>now()]);} }
